/* Données du cycle de volley-ball (Lycée G. Pompidou) : séances de Première et de Terminale,
   schémas, échauffements. Partagées par l'outil complet (index.html) et l'écran terrain (terrain.html).
   Modifier une séance ici la modifie dans les deux. */
let SID=0;
const S=36, MX=1.2, MY=0.7;
const X=m=>(m+MX)*S, Y=m=>(m+MY)*S;
function arrowPath(a,b,bend){
  const [x1,y1]=[X(a[0]),Y(a[1])],[x2,y2]=[X(b[0]),Y(b[1])];
  if(!bend) return {d:`M${x1},${y1} L${x2},${y2}`,end:[x2,y2],from:[x1,y1]};
  const mx=(x1+x2)/2,my=(y1+y2)/2,dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy)||1;
  const cx=mx-dy/len*bend*S, cy=my+dx/len*bend*S;
  return {d:`M${x1},${y1} Q${cx},${cy} ${x2},${y2}`,end:[x2,y2],from:[cx,cy]};
}
function court(sp){
  const id='s'+(++SID);
  const W=(14+2*MX)*S,H=(7+2*MY)*S;
  let g=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${sp.alt||'Schéma de terrain'}" xmlns="http://www.w3.org/2000/svg">
  <defs>
   <marker id="${id}b" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" class="c-head-b"/></marker>
   <marker id="${id}r" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" class="c-head-r"/></marker>
  </defs>
  <rect class="c-floor" x="${X(0)}" y="${Y(0)}" width="${14*S}" height="${7*S}" rx="2"/>
  <rect class="c-line" x="${X(0)}" y="${Y(0)}" width="${14*S}" height="${7*S}"/>
  <line class="c-att" x1="${X(4)}" y1="${Y(0)}" x2="${X(4)}" y2="${Y(7)}"/>
  <line class="c-att" x1="${X(10)}" y1="${Y(0)}" x2="${X(10)}" y2="${Y(7)}"/>
  <line class="c-net" x1="${X(7)}" y1="${Y(-0.4)}" x2="${X(7)}" y2="${Y(7.4)}"/>`;
  (sp.shadow||[]).forEach(z=>{g+=`<polygon class="c-shadow" points="${z.map(p=>X(p[0])+','+Y(p[1])).join(' ')}"/>`});
  (sp.zones||[]).forEach(z=>{g+=`<rect class="c-zone" x="${X(z.x)}" y="${Y(z.y)}" width="${z.w*S}" height="${z.h*S}" rx="4"/>`; if(z.t) g+=`<text class="c-zonet" x="${X(z.x)+5}" y="${Y(z.y)+14}">${z.t}</text>`});
  (sp.targets||[]).forEach(t=>{g+=`<circle class="c-target" cx="${X(t.x)}" cy="${Y(t.y)}" r="${(t.r||0.6)*S}"/>`; if(t.t) g+=`<text class="c-label" x="${X(t.x)}" y="${Y(t.y)+4}" text-anchor="middle">${t.t}</text>`});
  (sp.cones||[]).forEach(c=>{g+=`<path class="c-cone" d="M${X(c[0])-6},${Y(c[1])+6} L${X(c[0])},${Y(c[1])-7} L${X(c[0])+6},${Y(c[1])+6} z"/>`});
  (sp.runs||[]).forEach(r=>{const p=arrowPath(r[0],r[1],r[2]||0);g+=`<path class="c-run" d="${p.d}" marker-end="url(#${id}r)"/>`});
  (sp.balls||[]).forEach(r=>{const p=arrowPath(r[0],r[1],r[2]===undefined?0.6:r[2]);g+=`<path class="c-ball" d="${p.d}" marker-end="url(#${id}b)"/>`});
  (sp.players||[]).forEach(p=>{const cls=p.team==='b'?'c-pb':p.team==='n'?'c-pn':'c-pa';g+=`<circle class="${cls}" cx="${X(p.x)}" cy="${Y(p.y)}" r="${(globalThis.COURT_PR||0.36)*S}"/><text class="c-pt" x="${X(p.x)}" y="${Y(p.y)}">${p.l||''}</text>`});
  (sp.says||[]).forEach(s=>{g+=`<text class="c-say" x="${X(s.x)}" y="${Y(s.y)}" text-anchor="middle">${s.t}</text>`});
  (sp.labels||[]).forEach(s=>{g+=`<text class="c-label" x="${X(s.x)}" y="${Y(s.y)}" text-anchor="${s.a||'middle'}">${s.t}</text>`});
  g+=`</svg>`;
  return g;
}
const LEGEND=`<div class="legend"><span><i class="dot" style="background:var(--accent)"></i>équipe qui travaille</span><span><i class="dot" style="background:var(--team-b)"></i>serveur / lanceur / adversaire</span><span><i class="dot" style="background:var(--team-n)"></i>observateur / neutre</span><span><i class="lineb"></i>trajet du ballon</span><span><i class="liner"></i>déplacement du joueur</span><span>tirets blancs : lignes des 3 m</span></div>`;

