const BEGINNERS=[
 {t:'Passe haute : du blocage à la passe',d:'15 min',k:'Passe · tirée de tes leçons de 3e',sch:'debpasse',disp:'Par 2 de part et d’autre du filet (2,30 m), 1 ballon. Placer ces élèves sur un même terrain pendant que les autres font l’exercice principal.',deroul:['N1 : je bloque brièvement au-dessus du front puis je relance à 10 doigts.','N2 : passe à soi, puis passe au partenaire.','N3 : passes directes ; après chaque passe, je me décale de 3 pas.','N4 : après chaque passe, je prends la place de mon partenaire.'],cons:['Je suis sous la balle avant qu’elle arrive.','Mains en griffe, triangle pouces-index au-dessus du front, coudes écartés.','La poussée part des jambes. La paume ne touche jamais la balle.','Moins de bruit au contact = bonne passe.'],reus:'10 passes de suite pour passer au niveau suivant (8 au N3).',moins:'Ballon scolaire plus léger (recommandation FFVB) : moins d’appréhension, mêmes gestes.',plus:'Rejoindre l’exercice principal dès le N3 réussi.'},
 {t:'Manchette avec déplacement',d:'10 min',k:'Réception · leçons 4-5 de 3e',sch:'debmanchette',disp:'Par 2, un lanceur et un réceptionneur de part et d’autre du filet. 10 lancers, puis on change.',deroul:['Le lanceur envoie à la main à 1 m à droite, puis à gauche.','Le réceptionneur se déplace en pas chassés, s’arrête, frappe en manchette vers le lanceur.'],cons:['Contact sur le plateau des avant-bras, pas sur les poignets.','Très fléchi ; les bras ne remontent pas : ce sont les jambes qui montent la balle.','Je m’arrête avant de frapper.'],reus:'8 réceptions sur 10 qui reviennent dans les mains du lanceur.',moins:'Lancer droit sur le réceptionneur.',plus:'Service au lieu du lancer, puis manchette + passe.'},
 {t:'Service : contrat de distance',d:'10–15 min',k:'Service · leçons 3-5 de 3e',sch:'debservice',disp:'Plots dans son camp à 3, 4, 5, 6 et 7 m du filet. 1 ballon par élève, servir vers le camp adverse.',deroul:['Je commence au plot 1 (3 m du filet).','4 services réussis sur 5 : je recule d’un plot. Moins de 2 sur 5 : j’avance d’un plot.','Le référentiel accepte un service dans le terrain s’il dépasse la ligne des 3 m adverse : avant S8, fixe avec l’élève le plot d’où il servira le jour de l’épreuve.'],cons:['Pied opposé au bras frappeur devant, épaules tournées vers la cible.','Je place la balle sur la trajectoire de ma main : je la lâche, je ne la lance pas en l’air (service par le bas) ou je la lance à 50 cm, dans l’axe de l’épaule (service tennis).','Bras gainé au moment du contact, main ferme.','Je finis le geste la main tendue vers l’endroit visé.'],reus:'En S8 : 4 services sur 5 réussis depuis le plot choisi pour l’épreuve.',moins:'Service par le bas, main ouverte.',plus:'Service tennis dès le plot 3.'},
 {t:'Lire la trajectoire',d:'5 min',k:'Placement · situation collège',disp:'1 ballon par élève.',deroul:['Lancer la balle haut au-dessus de soi, faire une action pendant la descente (s’accroupir et taper le sol, faire un tour sur soi), puis rattraper.','Lancer à 3 m devant soi, courir, se placer sous la balle, la rattraper au-dessus du front.'],cons:['Je regarde la balle dès qu’elle part.','J’arrive sous la balle avant elle, je ne cours pas en même temps.'],reus:'5 réussites de suite.',plus:'Rattraper par une passe à soi.'},
 {t:'Attraper puis relancer, avec tour de plot',d:'10 min',k:'Passe · Carine',disp:'1c1 de part et d’autre du filet, un plot derrière chaque joueur. Service par un envoi à deux mains derrière les 3 m.',deroul:['L’adversaire attrape à deux mains au-dessus de la tête, face au filet, et relance sans bouger.','Après chaque renvoi, je fais le tour de mon plot.','Évolution : intercepter à une main, laisser rebondir une fois pour se rapprocher du filet, puis renvoyer en passe.'],cons:['J’attrape au niveau de la tête, dans l’axe des épaules.','Je suis placé avant que la balle arrive.'],reus:'10 échanges sans chute.',plus:'Match en 10 points : marquer dans un espace libre.'},
 {t:'Service : main ferme et poignet fixe',d:'10 min',k:'Service · Carine',disp:'Par équipe de 4 : 2 joueurs de chaque côté du filet, 2 ballons.',deroul:['Faire rebondir le ballon au sol d’une main, le frapper en main basse avec l’autre pour lui faire passer le filet.','Puis service réglementaire en main basse : se pencher en avant, soulever à peine le ballon avant de le frapper.','Servir derrière les 3 m précisément sur le partenaire ; reculer d’un mètre après chaque service réussi.'],cons:['Appuis décalés, opposés à la main qui frappe.','Main grande ouverte, poignet fixe, corps gainé.','Frappe sèche : on ne cherche pas la force.'],reus:'Atteindre la ligne de fond en reculant mètre par mètre.'},
 {t:'Intégrer le 4c4 avec un aménagement',d:'pendant les jeux à thème',k:'Jeu',disp:'Dans le 4c4 du jour, l’élève débutant a droit à un aménagement personnel, connu des deux équipes.',deroul:['Ballon bloqué en 1re ou en 2e touche : c’est l’aménagement prévu par ton référentiel (illimité, ou limité par set, par équipe ou par joueur).','Service à la cuillère ou dans le terrain, depuis le plot atteint dans le contrat de distance.','On réduit le nombre de ballons bloqués autorisés à chaque séance (par exemple 5, puis 3, puis 1 par rencontre).'],cons:['Le ballon bloqué reste possible le jour de l’épreuve, mais le référentiel l’associe aux degrés 1 et 2 de l’élément 2 : l’élève qui veut viser le degré 3 doit jouer sans.','Fixe la limite (par set, par équipe ou par joueur) avant S8 et applique-la au tournoi blanc.'],reus:'En S8, l’élève joue avec la limite qui sera appliquée le jour de l’épreuve.'}
];

const SESSIONS=[
 {id:'s1',n:'S1',short:'Éval diag · passe · 3c3',status:'done',title:'Évaluation diagnostique : passe, service, 3c3',lead:'Faite. Passe à deux en progression, service, puis matchs en 3c3 pour repérer les profils et former les groupes.',tl:[['Échauffement','12'],['Passe à 2 en progression','20'],['Service','10'],['Match 3c3','27'],['Bilan','6']],eval:[['e1','Profil de départ de chaque élève en passe haute et au service : point de départ pour mesurer les progrès.'],['e2','En 3c3 : renvoi en 1 touche, relais ou construction en 3 touches ? Repère de départ pour l’élément 2.']],warm:'Échauffement guidé, puis passes libres par 2.',ex:[
  {moins:"Partenaire à 2 m ; on reste à l'étape 1 (stop balle) jusqu'à 10 échanges.",plus:"Partenaire à 5 m, puis passe en suspension ou passe arrière une fois sur deux.",t:'Passe à 2 en progression',d:'20 min',k:'Diagnostic de la passe',sch:'debpasse',disp:'Par 2, un ballon pour deux, à 3–4 m l’un de l’autre.',deroul:['Étape 1 : stop balle puis passe haute (j’attrape au-dessus du front, je relance en passe).','Étape 2 : double touche (autopasse, puis passe au partenaire).','Étape 3 : double touche puis balle frappée haut vers le partenaire.','On passe à l’étape suivante quand le binôme tient 10 échanges.'],cons:['Observer : à quelle étape chaque binôme s’arrête-t-il ? La balle part-elle haute ?'],reus:'Noter l’étape atteinte par chaque élève.'},
  {fixe:"Diagnostic : mêmes conditions pour tous. Seul le choix cuillère ou tennis et la distance appartiennent à l'élève.",t:'Service',d:'10 min',k:'Diagnostic du service',sch:'debservice',disp:'Plots à 3, 4, 5, 6 et 7 m du filet. Chacun sert depuis la distance où il réussit.',deroul:['10 services par élève, cuillère ou tennis, au choix.','Noter la distance et le nombre de services réussis.'],cons:['Observer : quel service, depuis quelle distance, avec quelle régularité ?'],reus:'Chaque élève connaît sa distance de départ.'},
  {fixe:"Match d'observation : pas d'aménagement, pour voir le vrai niveau de jeu de chacun.",t:'Match 3c3',d:'27 min',k:'Constitution des groupes',sch:'tri3',disp:'3c3, équipes par affinité, matchs courts, on change d’adversaire.',deroul:['3 touches maximum par équipe.','Le prof note pour chaque élève : renvoi en 1 touche, relais, 3 touches, smash.'],cons:['Former les divisions et des équipes de force proche entre elles.'],reus:'Groupes prêts pour la suite du cycle.'}
 ],bilan:'Les élèves renvoient surtout en 1 touche ? Alors la priorité de S2 est la réception haute vers un partenaire.',check:'Vérifie que tes équipes sont stables à partir de S4 : l’ajustement de l’AFL1 par les matchs gagnés n’a de sens qu’avec des équipes de force proche.'},
 {id:'s2',n:'S2',short:'Passe · réception',status:'done',title:'Passe et réception en progression',lead:'Faite. Passe à deux et passe et suit, puis réception : d’abord sans filet sur balle lancée, ensuite une progression en 4 niveaux jusqu’à réception-passe-attaque.',tl:[['Échauffement','12'],['Passe à 2, passe et suit','12'],['Réception sans filet','15'],['Réception en 4 niveaux','30'],['Bilan','6']],eval:[['e1','Degré 2 : réception en manchette en situation favorable, jeu en relais.'],['e1','Degré 3 : passe et manchette hautes même en situation défavorable ; coordination réceptionneur-passeur.']],warm:'Routine type, puis manchettes sur lancer par 2.',ex:[
  {moins:"Le partenaire lance à deux mains, l'élève renvoie en passe ; ballon plus léger si possible.",plus:"Passe et suit à 4 avec un 2e ballon, ou passe arrière une fois sur trois.",t:'Passe à 2, puis passe et suit',d:'12 min',k:'Passe haute',sch:'triangle',disp:'Par 2 d’abord, puis en triangle à 3 ou 4 : on suit sa balle.',deroul:['Passes hautes par 2.','Passe et suit : je passe et je prends la place de celui à qui j’ai passé.'],cons:['Se placer sous la balle avant de la toucher ; balle haute.'],reus:'15 passes de suite sans que la balle tombe.'},
  {moins:"Lancer droit sur le réceptionneur, à 2 m ; il a le droit d'attraper après la manchette.",plus:"Lancer à 2 m sur les côtés puis en avant et en arrière ; renvoi visé dans un cerceau.",t:'Réception sans filet, balle lancée par en dessous',d:'15 min',k:'Manchette',sch:'debmanchette',disp:'Par 2 ou 3, sans filet. Le lanceur envoie la balle à deux mains par en dessous.',deroul:['Le réceptionneur renvoie en manchette haute sur le lanceur.','Le lanceur décale peu à peu ses lancers à gauche et à droite.'],cons:['Plateau formé tôt, jambes fléchies, s’arrêter avant de toucher.'],reus:'7 manchettes sur 10 attrapées par le lanceur sans qu’il bouge.'},
  {moins:"Service remplacé par un lancer à deux mains depuis les 3 m ; on valide un niveau à 5 sur 10.",plus:"Service tennis derrière la ligne ; le passeur doit jouer en suspension.",t:'Réception en 4 niveaux',d:'30 min',k:'Liaison réception → passeur',sch:'lrp',disp:'Groupes de 3 ou 4 au filet. Chaque groupe avance d’un niveau quand il réussit 7 sur 10.',deroul:['Niveau 1 : réception sur service simple.','Niveau 2 : réception vers le passeur, qui attrape bras tendus au-dessus de la tête.','Niveau 3 : réception, le passeur repasse à l’attaquant.','Niveau 4 : réception, passe, attaque.'],cons:['Le passeur est déjà placé près du filet avant le service.'],reus:'Noter le niveau atteint par chaque groupe.'}
 ],bilan:'Où doit arriver la réception pour que le passeur puisse jouer ? (Haut, en zone avant, devant lui.)',check:'En S4, la réception notée de 0 à 3 vérifie que la liaison vers le passeur tient en 4c4.'},
 {id:'s3',n:'S3',short:'4c4 · service',status:'done',title:'Passage au 4c4 et introduction du service réglementaire',lead:'Faite. Forme de l’épreuve en place ; service réglementaire introduit, pas encore maîtrisé.',tl:[['Échauffement','12'],['Service-réception par 2','15'],['Règles + 4c4 réception obligatoire','27'],['4c4 libre','15'],['Bilan','6']],eval:[['e1','Service : chaque joueur servira 3 fois de suite le jour de l’épreuve.'],['e2','Première organisation à 4 : qui reçoit, qui passe.']],warm:'Routine type, puis volleython.',ex:[
  {moins:"Service cuillère depuis les 3 m ; le réceptionneur peut attraper après sa manchette.",plus:"Service annoncé sur une zone (1, 6 ou 5) ; le réceptionneur enchaîne manchette, passe à soi et renvoi par-dessus le filet.",t:'Service-réception par 2',d:'15 min',k:'Introduction du service',sch:'sr2',disp:'Par 2 de part et d’autre du filet, 1 ballon.',deroul:['Service par en dessous puis tennis, d’abord depuis les 3 m, puis on recule.','Le réceptionneur joue en manchette, passe à soi, attrape.'],cons:['Pied opposé au bras frappeur devant ; main ferme ; finir vers la cible.'],reus:'Chaque élève repère la distance d’où il réussit 4 services sur 5.'},
  {moins:"Engagement lancé à deux mains ; la réception peut être bloquée (attraper-relancer) par le passeur.",plus:"Point marqué en 3 touches = 2 points ; service tennis obligatoire au-delà des 3 m.",t:'Règles puis 4c4 réception obligatoire',d:'27 min',k:'Jeu',sch:'eval4',disp:'3 min de règles sur un terrain de démonstration (postes, rotation, 3 services de suite, service au-delà des 3 m adverses), puis 4c4 en matchs de 7 min.',deroul:['Réception obligatoire vers le joueur avant (passeur) avant tout renvoi.','Service depuis la distance choisie par chaque élève.'],cons:['Le joueur avant est le passeur.'],reus:'La moitié des points construits en 3 touches.'},
  {moins:"Filet abaissé de 10 cm ; une balle bloquée autorisée par échange pour les débutants.",plus:"Point en 3 touches = 2 points ; balle facile renvoyée = point pour l'adversaire.",t:'4c4 libre',d:'15 min',k:'Jeu',sch:'eval4',disp:'4c4, rencontres de 12 points au tie-break.',deroul:['Règles de l’épreuve.'],cons:['Le prof note les services ratés par joueur.'],reus:'Repérer les élèves dont le service n’est pas fiable : priorité de S4.'}
 ],bilan:'Combien de points perdus au service ? C’est le premier chantier de S4.',check:'Le référentiel autorise un service à la cuillère ou tennis, dans le terrain ou derrière la ligne, à condition qu’il dépasse la ligne des 3 m adverse. Chaque élève choisit son service d’épreuve et le stabilise de S4 à S8.'},
 {id:'s4',n:'S4',short:'Service · réception · attaque',status:'today',title:'Servir, recevoir en communiquant, attaquer',lead:'Deux exercices fil rouge qui reviendront à chaque séance, puis un 4c4 à thème : l’équipe s’annonce, se déplace avant la réception et termine en 3 touches.',tl:[['Échauffement d’équipe','12'],['Service et réception notée','15'],['Attaque à 4','15'],['4c4 en rotation, 3 tours','27'],['Bilan','6']],eval:[['e1','Communication et soutien du non-porteur = repères du degré 3.'],['e1','Service : 3 fois de suite le jour de l’épreuve. Chaque élève fixe son service (cuillère ou tennis, dans le terrain ou derrière la ligne) avant S8.'],['a3','Dernier délai pour choisir les 2 rôles et la répartition AFL2/AFL3 ; arbitre et coach en priorité (les deux rôles décrits par le référentiel). En S4 et S5, auto-arbitrage : les arbitres seront évalués en S6 et S8, sur les rotations à 2 terrains.']],warm:'Échauffement d’équipe, première fois : présente la fiche (2 min), puis général 3 min, spécifique 2, cheville-épaule et gainage 2, travail ciblé 5. Le coach de la séance remplit le carnet. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Fil rouge 1 · Service et réception notée de 0 à 3',d:'15 min',k:'Service · communication · déplacements',sch:'recep',four:'4 au service : chacun sert 3 fois de suite, puis note la réception pendant que le suivant sert. 4 en réception : 3 réceptionneurs + 1 passeur ; rotation d’une place après chaque série de 3 services.',disp:'Par terrain : une équipe de 4 au service (chacun sert 3 fois de suite, comme à l’épreuve), une équipe de 4 en réception : 3 réceptionneurs et 1 passeur décalé dans la zone cible (2 × 2 m au sol, à 1 m du filet, entre les postes 2 et 3). 12 services, puis on inverse.',deroul:['Dès la frappe du serveur, tout le monde bouge.','Le réceptionneur annonce « j’ai » avant que le ballon passe le filet ; les deux autres pivotent vers lui en soutien.','Le passeur lève le bras (« ici ») et attrape la réception dans la zone cible.','Le coach de l’équipe note chaque réception de 0 à 3.','Débutants au service : depuis le plot de leur contrat de distance.'],cons:['Réceptionneur : plateau tôt, immobile, orienté vers la zone cible ; ce sont les jambes qui donnent la hauteur.','Serveur : pied opposé au bras frappeur devant, lancer à 50 cm dans l’axe de l’épaule, main ferme.'],reus:'Réception : moyenne de l’équipe au moins 1,5 sur 3. Service : 9 sur 12 au-delà des 3 m adverses. Ballon tombé entre deux joueurs sans annonce = 0 et on recommence l’annonce à voix haute.',moins:'Service remplacé par un lancer à deux mains depuis les 3 m.',plus:'Service ciblé sur un réceptionneur ; le passeur fait la vraie passe et le réceptionneur attaque.'},
  {t:'Fil rouge 2 · Attaque à 4',d:'15 min',k:'Attaque',sch:'att3',four:'Lanceur, passeur, attaquant d’un côté ; le 4e, en face, défend la balle attaquée et la rend au lanceur. Rotation à chaque ballon : lanceur → passeur → attaquant → défenseur → lanceur.',disp:'Par équipe de 4 sur un demi-terrain dans la longueur (2 équipes par terrain), 2 ballons par équipe pour ne pas attendre.',deroul:['Le lanceur envoie haut au passeur placé dans la zone cible.','Le passeur fait une passe haute vers le poste 4, à 1 m du filet.','L’attaquant, parti derrière les 3 m quand la balle quitte les mains du passeur, attaque.','D2 : attaque avec saut au choix — poussée au fond, balle courte, smash.','D1 : smash vers une cible annoncée (ligne ou diagonale).'],cons:['Dernier appui en blocage des 2 pieds, bras tirés en arrière.','Saut vers le haut, pas vers le filet ; frapper au plus haut, balle devant l’épaule.'],reus:'D2 : 6 attaques sur 10 dans le terrain, avec saut. D1 : 5 smashs sur 10 dans la cible.',moins:'Filet abaissé de 10 cm ; attaque sans saut.',plus:'Le défenseur doit remettre la balle défendue dans la zone cible de son camp : 1 point pour lui.'},
  {moins:"Tours 1 à 3 en engagement en passe ; le ballon bloqué est autorisé à la 2e touche.",plus:"Dès le tour 2, vrai service ; le point en 3 touches compte double.",t:'4c4 en rotation, 3 tours',d:'27 min',k:'Jeu · 6 équipes mixtes',sch:'eval4',four:'Les 6 équipes jouent en même temps sur 3 terrains, les 4 joueurs sur le terrain. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point.',disp:'Tournoi à 3 terrains (bouton Tournoi), tours 1 à 3 : matchs de 7 min (ou 12 points), 1 min de changement. 3 min pour présenter les thèmes et la rotation.',deroul:['Tours 1 et 2 : l’équipe au service engage en passe (pas de service frappé) pour multiplier les constructions.','Tour 3 : vrai service, règles de l’épreuve (3 services de suite, rotation à la récupération).','Barème de l’épreuve : attaque en suspension vers le bas = 3 points ; ballon non touché = 3 points.','Thème : ballon tombé entre deux joueurs sans annonce = 2 points de plus pour l’adversaire.'],cons:['Au bilan de fin de séance, chaque équipe fait le point : services ratés, ballons tombés sans annonce.'],reus:'Plus de la moitié des points de l’équipe marqués en 3 touches.'}
 ],bilan:'Moyenne de réception de l’équipe ? Nombre de ballons tombés entre deux joueurs ? Ces deux chiffres reviennent en S5.'},
 {id:'s5',n:'S5',short:'Réception · transition',status:'next',title:'Recevoir sous pression, attaquer, rejouer la balle facile',lead:'Les deux fils rouges reviennent avec une difficulté de plus, et le 4c4 introduit la transition : après le service, l’équipe doit aussi gagner la balle facile.',tl:[['Échauffement d’équipe','12'],['Réception notée sous service ciblé','15'],['Alternative smash','15'],['Grand point / petit point, 3 tours','27'],['Bilan','6']],eval:[['e1','Utilisation efficace de plusieurs techniques d’attaque = degré 3.'],['e2','Premier temps mort d’1 min : adapter le jeu au score.'],['a2','Premier échauffement autonome évalué ; fiche d’équipe et auto-évaluation N1-N3.']],warm:'Échauffement d’équipe en autonomie avec la fiche. Premier passage évalué pour l’AFL2 : choix de l’axe, respect de la règle 7 sur 10, carnet rempli. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Fil rouge 1 · Réception notée sous service ciblé',d:'15 min',k:'Service · réception',sch:'recep',four:'4 au service : chacun sert 3 fois de suite, puis note la réception pendant que le suivant sert. 4 en réception : 3 réceptionneurs + 1 passeur ; rotation d’une place après chaque série de 3 services.',disp:'Même dispositif qu’en S4 (4 au service, 3 réceptionneurs + passeur dans la zone cible).',deroul:['Le serveur vise une zone faible : poste 1, poste 5, ou la zone de divorce entre deux réceptionneurs.','Réception notée de 0 à 3 ; le coach calcule la moyenne de chaque réceptionneur.','Le passeur fait la vraie passe ; le réceptionneur noté 2 ou 3 attaque.'],cons:['Le joueur du centre prend les balles entre deux réceptionneurs.','Sur service fort : relâcher le haut du corps, amortir.'],reus:'Réception : moyenne de l’équipe au moins 1,8. Service : 8 sur 12 dans la cible.',moins:'Service non ciblé.',plus:'Service fort non annoncé.'},
  {t:'Fil rouge 2 · Alternative smash',d:'15 min',k:'Attaque · SRP niveau 3',sch:'srp',four:'1 lanceur + réceptionneur, passeur, attaquant : rotation d’une place tous les 5 lancers.',disp:'Demi-terrain dans la longueur, par équipe de 4 : 1 lanceur contre 3 joueurs (réceptionneur, passeur dans la zone cible, attaquant). 2 équipes par terrain, chacune sur sa moitié.',deroul:['Le lanceur fait 5 lancers en cloche vers le fond puis tourne.','Les 3 joueurs renvoient en 3 touches maximum, trajectoire descendante.','Le point compte si le lanceur ne peut pas toucher la balle.'],cons:['Passe mi-haute : je pars à la touche du passeur ; passe haute : je pars quand la balle est en haut.','Frappe au-dessus et en arrière de la balle.'],reus:'6 renvois descendants non touchés sur 10.',moins:'Touches illimitées.',plus:'Le lanceur monte au contre (D1 seulement) ou recule défendre.'},
  {moins:"La balle facile est lancée depuis les 3 m, en cloche, au centre du terrain.",plus:"La balle facile est lancée vers un joueur ciblé ; la 2e balle est smashée par l'enseignant.",t:'Grand point / petit point, 3 tours',d:'27 min',k:'Jeu · transition',sch:'grandpoint',four:'Les 6 équipes jouent sur 3 terrains. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point. La balle facile est lancée par un joueur de l’équipe qui a gagné le premier échange.',disp:'Tournoi à 3 terrains (bouton Tournoi), 3 tours de 7 min, 1 min de changement.',deroul:['Chaque échange commence par un vrai service.','Dès qu’il se termine, l’équipe qui l’a gagné lance une balle facile (à deux mains, par-dessus le filet) à l’autre équipe.','L’équipe qui gagne les deux échanges marque le grand point ; sinon personne ne marque.','Sur la balle facile, toute l’équipe crie « facile ! » et se replace en réception avant de construire en 3 touches.'],cons:['Au bilan de fin de séance : combien de balles faciles gagnées par l’équipe ?'],reus:'Gagner au moins la moitié des balles faciles reçues.'}
 ],bilan:'Fiche d’équipe AFL2 : un point fort, un point faible, le terrain qu’on choisira en S8. Chaque élève se situe sur la grille d’auto-évaluation de Carine (N1, N2, N3).'},
 {id:'s6',n:'S6',short:'Défense · transition',status:'next',title:'Défendre et contre-attaquer',lead:'Défense basse et soutien pour tous ; contre seulement pour la division forte, et seulement quand la passe adverse est près du filet.',tl:[['Échauffement d’équipe','12'],['Attaque contre défense 4c4','15'],['Balle facile','15'],['4c4 en rotation, 3 tours','27'],['Bilan','6']],eval:[['e1','Défense sur balle basse ou éloignée, contre et soutien du contre = degrés 3 et 4.'],['a3','Arbitrage évalué pendant le 4c4.']],warm:'Échauffement d’équipe avec la fiche. D1 : en partie 3, 3 séries de 5 sauts de contre en pas chassés (retombée sur place) remplacent le gainage. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Attaque contre défense en 4c4',d:'15 min',k:'Défense · soutien · contre (D1)',sch:'attdef',four:'Attaque : lanceur, passeur, attaquant, et un soutien qui couvre l’attaquant. Défense : D2 = 3 défenseurs bas + 1 passeur dans la zone cible ; D1 = 1 contreur + 2 défenseurs hors de l’ombre du contre + 1 passeur. Rotation d’une place toutes les 3 attaques.',disp:'Deux équipes de 4 sur un terrain. 10 attaques, puis on inverse.',deroul:['Le lanceur envoie au passeur, passe en poste 4, attaque ; le soutien se place à 1,5 m de l’attaquant pour récupérer un ballon contré.','En défense, le ballon défendu va au passeur dans la zone cible, qui fait jouer la contre-attaque.','D1 : le contreur ne saute que si la passe adverse est à moins d’1 m du filet.'],cons:['Défenseur : fléchi avant la frappe, bras devant, on amortit.','Contreur : regarder l’attaquant, pas le ballon ; mains au-dessus du filet ; retomber sur place, sur deux pieds, jamais au-delà de la ligne centrale.'],reus:'1 point par défense qui arrive dans la zone cible. 5 points sur 10 attaques.',moins:'Attaques sans saut.',plus:'D1 : smash après bloc (les deux avants contrent, l’un devient passeur, l’autre recule aux 3 m et attaque).'},
  {moins:"Balle facile lancée haut et au centre ; construction validée dès la passe réussie.",plus:"Balle facile envoyée sur un côté ou en profondeur ; l'attaque doit viser la zone arrière.",t:'Balle facile',d:'15 min',k:'Transition',sch:'grandpoint',four:'2 équipes par terrain (3 terrains). Chaque équipe lance à tour de rôle 10 balles faciles à l’autre ; le lanceur change à chaque balle, les 3 autres défendent.',disp:'4c4 sur 3 terrains, 10 balles faciles par équipe.',deroul:['Au lancer, l’équipe crie « facile ! » et prend sa place de réception (3 réceptionneurs, passeur dans la zone cible).','Construction en 3 touches et attaque.','L’autre équipe défend puis contre-attaque si elle récupère le ballon.'],cons:['Se replacer pendant que la balle est en l’air, pas après.'],reus:'7 constructions en 3 touches sur 10 balles faciles.'},
  {moins:"Équipes de niveau ; engagement en passe pendant les 3 tours.",plus:"Contre-attaque gagnante = 3 points ; vrai service dès le tour 2.",t:'4c4 en rotation à 2 terrains, 3 tours',d:'27 min',k:'Jeu · arbitrage évalué',sch:'eval4',four:'4 équipes jouent sur 2 terrains ; les 2 autres arbitrent, une par terrain : 1 arbitre, 2 juges de ligne, 1 coach pour une des équipes qui jouent. Le 3e terrain sert à l’échauffement de l’équipe suivante.',disp:'Tournoi à 2 terrains, arbitres cochés (bouton Tournoi), tours 1 à 3 : matchs de 7 min (ou 12 points), 1 min de changement. Équipes de niveau ou mixtes, au choix de la séance.',deroul:['Tours 1 et 2 : engagement en passe ; tour 3 : vrai service.','Contre gagnant = 3 points (D1).','Ballon défendu puis contre-attaque gagnante = 2 points.'],cons:['Arbitre évalué (AFL3) : debout, siffle chaque mise en jeu, score serveur en premier, gestes in/out, faute de filet, 4 touches, ballon porté.'],reus:'Au moins 2 contre-attaques gagnantes par match.'}
 ],bilan:'Où se placer quand l’adversaire attaque en poste 4 ? Pour les arbitres, quiz de 5 min (fiche de Carine) : ordre des gestes, règles du service, postes et rotation, particularités du poste 1.'},
 {id:'s6b',n:'S6 bis',short:'Losange · lire la balle',status:'next',nopdf:true,title:'S’organiser en losange, communiquer, choisir 2 ou 3 touches',lead:'Séance de remédiation après le tournoi de S5 : balles qui tombent dans le carré central sans être touchées, aucune annonce, 3 touches forcées même sur une balle attaquable, 3e touche rendue au passeur. On fixe des rôles nommés (P, G, D, A) et des règles de match qui sanctionnent ces trois erreurs. Équipes stables. Elle remplace S6 ce jour-là : S6 reste disponible.',tl:[['Échauffement d’équipe','12'],['Réception en losange et annonces','15'],['Match à thème « lire la balle »','15'],['4c4 à 2 terrains, arbitres et coachs','27'],['Bilan','6']],eval:[['e1','Communication, soutien du non-porteur et organisation collective = repères du degré 3.'],['e2','Choisir entre renvoi direct et construction selon la balle reçue : c’est ce que note l’élément 2.'],['a3','Arbitrage évalué pendant le 4c4 (rotation à 2 terrains) ; le coach note deux indicateurs.']],warm:'Échauffement d’équipe avec la fiche. Partie spécifique : passes à 2 avec annonce obligatoire « j’ai ! » avant chaque touche ; ballon touché sans annonce = la série repart à zéro. Début de séance : 2 min au tableau pour nommer les rôles P, G, D, A et la règle de priorité au centre. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Réception en losange et annonces',d:'15 min',k:'Organisation · communication',sch:'losange6b',four:'4 au service : chacun sert 3 fois de suite, puis note la réception. 4 en réception, en losange : P au filet (zone cible), G et D sur les côtés, A au centre en retrait. Rotation d’un poste après chaque série de 3 services, pour que chacun passe A.',disp:'Par terrain : une équipe au service, une équipe en losange. 12 services, puis on inverse. Le serveur vise volontairement le centre et les frontières entre deux joueurs.',deroul:['Avant le service, chaque joueur dit son rôle à voix haute : « P », « G », « D », « A ».','Le réceptionneur annonce « j’ai ! » avant que le ballon passe le filet ; le passeur répond « ici ! » bras levé.','Balle au centre ou entre deux joueurs : c’est A qui la prend ; G et D pivotent vers lui en soutien.','Le passeur joue la 2e touche vers G ou D, qui renvoie. Le passeur ne réceptionne jamais ; s’il est obligé de toucher la 1re, A devient passeur de secours.'],cons:['A : prêt, fléchi, au centre, un pas en arrière de G et D.','Annoncer tôt : avant que le ballon passe le filet, pas au moment de le toucher.'],reus:'+1 réception jouable au passeur ; +1 renvoi par G ou D ; −2 ballon qui tombe sans être touché. Objectif : 15 points sur 12 services.',moins:'Service remplacé par un lancer à deux mains depuis les 3 m.',plus:'Service ciblé sur une frontière, non annoncé.'},
  {t:'Match à thème « lire la balle »',d:'15 min',k:'Choisir 2 ou 3 touches',sch:'lire6b',four:'Les 6 équipes jouent en même temps sur 3 terrains (5 équipes : celle qui ne joue pas arbitre et compte). Auto-arbitrage : l’équipe au service annonce le score, le sien en premier.',disp:'Matchs de 4 min, on change d’adversaire 3 fois. Engagement en passe pour multiplier les constructions.',deroul:['Ballon qui tombe au centre sans être touché = 2 points pour l’adversaire.','3e touche jouée vers le passeur = point perdu.','Ballon touché sans annonce = point perdu.','Renvoi gagnant en 1 ou 2 touches sur une balle haute et près du filet = 2 points.'],cons:['Avant la 2e touche, regarder la balle : haute et près du filet → on attaque ; basse ou loin → on construit.','Annoncer « facile ! » ou « on construit ! » pour que toute l’équipe sache quoi faire.'],reus:'Moins de 2 ballons tombés au centre par match et aucune 3e touche rendue au passeur.',moins:'Ballon bloqué autorisé sur la passe.',plus:'Renvoi en 2 touches seulement s’il est descendant.'},
  {moins:"Le coach ne compte qu'une seule chose : les ballons tombés au centre.",plus:"Le coach donne un conseil à la mi-match et vérifie qu'il est appliqué.",t:'4c4 en rotation à 2 terrains, 3 tours',d:'27 min',k:'Jeu · arbitres et coachs',sch:'eval4',four:'4 équipes jouent sur 2 terrains ; les 2 autres arbitrent, une par terrain : 1 arbitre, 2 juges de ligne, 1 coach qui observe une des équipes qui jouent. Classe à 5 équipes : l’équipe libre fournit 1 arbitre et 1 coach.',disp:'Tournoi à 2 terrains, arbitres cochés (bouton Tournoi), matchs de 7 min + 1 min de changement. Équipes stables.',deroul:['Vrai service, barème de l’épreuve.','On garde une seule règle à thème : ballon tombé au centre sans être touché = 2 points de plus pour l’adversaire.','Le coach compte pour son équipe : ballons centraux non touchés, 3e touches non renvoyées. Il donne un seul conseil en fin de match.'],cons:['Arbitre évalué (AFL3) : debout, siffle chaque mise en jeu, score serveur en premier, gestes in/out, faute de filet, 4 touches.'],reus:'Les deux compteurs du coach baissent entre le 1er et le 3e match.'}
 ],bilan:'Chaque équipe dit qui est P, G, D, A et quelle est sa règle au centre. Combien de ballons sont tombés au centre au 1er puis au 3e match ? Ces deux chiffres reviennent en S7. Attention pour S9 : les écarts entre équipes stables sont grands (classe de 15h : Arthur et Anujin à −29 et −23) ; prévois une montée-descente ou des appariements par niveau pour les matchs de l’épreuve.'},
 {id:'s7',n:'S7',short:'Incertitude · projet',status:'next',title:'Créer l’incertitude et jouer un projet',lead:'Attaquer là où l’adversaire n’est pas, puis annoncer un projet et l’ajuster au temps mort. Équipes hétérogènes en leur sein : le meilleur joueur coache le plus faible.',tl:[['Échauffement d’équipe','12'],['Feinte ou smash','15'],['Supériorité numérique','15'],['Projet + 3 matchs','27'],['Bilan','6']],eval:[['e1','Variété des attaques (feinte, balle placée, smash) = degré 4.'],['e2','Projet annoncé puis ajusté au temps mort : c’est ce que note l’élément 2.'],['a3','Coach évalué au temps mort et à la concertation.']],warm:'Échauffement d’équipe avec la fiche. Une équipe qui n’a jamais choisi l’axe Service le prend aujourd’hui (série de 3, comme le jour J). <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {moins:"Le défenseur entre avant la passe : l'attaquant a plus de temps pour choisir.",plus:"Le défenseur entre au dernier moment, ou deux défenseurs entrent ; feinte en zone 1 ou 5 seulement.",t:'Feinte ou smash en 4 contre 4',d:'15 min',k:'Choisir son attaque',sch:'feinte',four:'Attaque : 1 lanceur, 1 passeur, 2 attaquants qui alternent. Défense : 2 défenseurs (un seul entre à chaque passe), 1 observateur qui compte les bons choix, 1 ramasseur qui rend les ballons au lanceur. On tourne dans l’équipe toutes les 5 attaques.',disp:'Deux équipes de 4 sur un demi-terrain dans la longueur. 10 attaques, puis on inverse.',deroul:['Au moment de la passe, un seul défenseur entre : au filet, ou au fond.','Défenseur au filet → l’attaquant feinte (poussée haute à une main, derrière lui).','Défenseur au fond → l’attaquant smashe.'],cons:['Regarder le terrain adverse pendant la passe.','Feinte : main ouverte, doigts tendus, au point le plus haut.'],reus:'Bon choix = 1 point ; attaque non défendue = 3 points. 7 bons choix sur 10.'},
  {t:'Supériorité numérique 4 contre 2',d:'15 min',k:'Jeu placé',sch:'sup',four:'Équipe en surnombre : les 4 jouent. Autre équipe : 2 défendent, 2 comptent les points et approvisionnent en ballons ; après 6 engagements, les deux paires échangent. Puis on inverse les équipes.',disp:'Une équipe de 4 contre 2 joueurs de l’autre équipe, 12 engagements en passe.',deroul:['Ballon non touché = 3 points ; touché une fois puis faute = 2 ; touché 2 ou 3 fois = 0.'],cons:['Regarder où sont les défenseurs avant de frapper.'],reus:'20 points sur 12 engagements.',plus:'4 contre 3 : le 4e de l’équipe qui défend devient observateur et note où tombent les ballons.'},
  {moins:"Fiche projet limitée à deux questions : qui reçoit, où est le passeur.",plus:"L'équipe change de projet au temps mort et le point « dans le projet » ne compte que s'il est annoncé.",t:'Projet d’équipe puis 3 matchs',d:'27 min',k:'Conditions de l’épreuve',sch:'eval4',four:'Les 6 équipes jouent sur 3 terrains. Dans chaque équipe, un joueur-coach (évalué en AFL3) mène le temps mort et la concertation. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point.',disp:'3 min de fiche projet au bord du terrain. Puis 3 matchs de 7 min (ou 12 points) : tours 1 et 2 contre le même adversaire (le référentiel prévoit au moins 2 rencontres contre la même équipe), avec 1 min de concertation entre les deux ; tour 3 contre un nouvel adversaire.',deroul:['Fiche projet : qui reçoit, où est le passeur, quels postes attaquent, smash ou balle placée selon quoi, contre ou pas, qui défend le milieu.','Projet du match : marquer en zone arrière / sur balle placée / sur smash / sur feinte.','Vrai service, barème de l’épreuve, 1 temps mort d’1 min par match ; un point marqué « dans le projet » vaut 1 point de plus.'],cons:['Joueur-coach : il dit au temps mort si le projet fonctionne et propose un seul ajustement.'],reus:'L’équipe change quelque chose de visible au 2e match quand le 1er est perdu.'}
 ],bilan:'Quel projet avez-vous joué ? A-t-il rapporté des points ? Qu’avez-vous changé au temps mort ? À la fin : distribue la fiche « Mes choix pour l’épreuve » (onglet Fiche d’évaluation), à rendre signée en S8.'},
 {id:'s8',n:'S8',short:'Tournoi blanc',status:'next',title:'Entraînement choisi et tournoi blanc',lead:'Dernière séance avant l’épreuve : chaque élève travaille son point faible, puis joue aux conditions exactes de l’évaluation.',tl:[['Échauffement d’avant-match','12'],['Entraînement choisi','20'],['Tournoi blanc','37'],['Bilan','6']],eval:[['a2','Choix du terrain cohérent avec la fiche de S5 = élément « s’entraîner » de l’AFL2.'],['e1','Tournoi blanc : chaque élève connaît son degré provisoire.'],['e2','Projets annoncés et ajustés au temps mort.'],['a3','Dernières observations des rôles.']],warm:'Échauffement d’avant-match mené par l’équipe seule, observé comme le jour de l’épreuve.',ex:[
  {moins:"Sur chaque terrain, on reprend la version − du fil rouge travaillé.",plus:"Sur chaque terrain, on reprend la version + du fil rouge, avec un adversaire qui défend.",t:'Entraînement choisi en 3 terrains',d:'20 min',k:'AFL2 · organisation de Carine',four:'Terrain 1 : 4 au service contre 3 réceptionneurs + 1 passeur. Terrain 2 : lanceur, passeur, attaquant, ramasseur contre 4 défenseurs dans les angles. Terrain 3 : fil rouge 2 contre une défense de 4.',disp:'Chaque équipe de 4 choisit son terrain d’après sa fiche de S5 (2 équipes par terrain) ; elle peut changer au bout de 15 min. Le coach de l’équipe réexplique l’exercice si l’équipe change.',deroul:['Terrain 1, service et réception : fil rouge 1 (réception notée de 0 à 3).','Terrain 2, passe et attaque placée : l’attaquant en poste 4 vise un des 4 adversaires placés dans les angles ; on change de rôle en suivant son ballon.','Terrain 3, attaque et défense : fil rouge 2 contre une défense (contre pour la D1).'],cons:['On écrit sur la fiche d’équipe : point faible → terrain choisi → résultat obtenu.'],reus:'Le terrain choisi correspond au point faible noté en S5.'},
  {fixe:"Tournoi blanc : conditions de l'épreuve. Seuls les aménagements du référentiel s'appliquent (service choisi, ballon bloqué selon la limite fixée).",t:'Tournoi blanc',d:'37 min',k:'Conditions de l’épreuve',sch:'eval4',four:'La 3e équipe : 1 arbitre, 2 juges de ligne, 1 gestionnaire (score, feuille de match).',disp:'Exactement l’organisation de S9 : poules de 3 équipes, rencontres de 12 points au tie-break, temps mort d’1 min, la 3e équipe fournit l’arbitre et 2 juges de ligne.',deroul:['Projet annoncé avant chaque rencontre.','Seulement les aménagements du référentiel : service choisi par l’élève, ballon bloqué selon la limite fixée.','Le prof place chaque élève dans un degré provisoire.'],cons:['Annoncer le degré provisoire à chaque élève en fin de séance.'],reus:'Tout le monde connaît les règles et l’organisation du jour J.'}
 ],bilan:'Chaque élève repart avec son degré provisoire en AFL1 et un point à améliorer pour le jour de l’épreuve.'},
 {id:'s9',n:'S9',short:'Évaluation',status:'eval',title:'Évaluation finale',lead:'Tournoi en 4c4 par poules de niveau. AFL1 noté le jour même ; AFL2 et AFL3 complétés avec les observations de S4 à S8.',evalPage:true}
];

/* ===== Tournoi : planification, saisie des scores, minuteur, classement ===== */
const P_SESSIONS=[
 {id:'p1',n:'S1',short:'Diagnostic',status:'next',title:'Diagnostic : continuité et premiers matchs',lead:'Un test chiffré, beaucoup de jeu à effectif réduit, puis des matchs en 3c3 pour former les groupes.',tl:[['Échauffement + volleython','12'],['Test continuité','10'],['Montante-descendante 1c1 puis 2c2','20'],['Match 3c3 d’observation','27'],['Bilan','6']],eval:[['a2','Premier record et premier niveau N1–N4 : point de départ pour mesurer les progrès.'],['e1','Profil de jeu observé en 3c3 (renvoi en 1 touche, relais, 3 touches).']],warm:'Échauffement guidé avec prévention, puis volleython par 2 (record en 1 min, à noter).',ex:[
  {fixe:"Test : mêmes conditions pour tous. Le score oriente ensuite vers la fiche de niveau.",t:'Test « continuité »',d:'10 min',k:'Thomas',sch:'debpasse',disp:'Par 2, de part et d’autre du filet, depuis la ligne des 3 m.',deroul:['Maximum de passes en 2 min, 3 fois avec un partenaire différent.','On garde le meilleur score.'],cons:['Le partenaire compte et valide.'],reus:'N1 < 20 · N2 20–30 · N3 30–40 · N4 > 40. Le niveau oriente vers la fiche « Assurer la continuité » (bouton Travail par niveaux).'},
  {moins:"1c1 : passe à soi autorisée avant le renvoi (2 touches) ; couloir de 2 m.",plus:"1c1 en 1 touche, couloir de 3 m ; en 2c2, l'attaque doit être frappée.",t:'Montante-descendante 1c1 puis 2c2',d:'20 min',k:'Thierry',sch:'kob',disp:'Couloirs de 2 à 3 m de large. 10 min en 1c1 (jusqu’à 2 touches par joueur), puis 10 min en 2c2 (3 touches par équipe). Matchs de 3 min, engagement en passe.',deroul:['Je gagne, je monte d’un terrain ; je perds, je descends.','En 2c2, la réception doit aller au partenaire avant tout renvoi.'],cons:['Viser la profondeur : le fond du couloir adverse.'],reus:'Monter d’au moins un terrain dans chaque format.'},
  {fixe:"Match d'observation : pas d'aménagement, pour voir le vrai niveau de jeu de chacun.",t:'Match 3c3 d’observation',d:'27 min',k:'Jeu',sch:'tri3',disp:'3c3, équipes par affinité, 7 × 14 m, filet à 2,24 m, matchs courts, on change d’adversaire, engagement en passe.',deroul:['Le prof note pour chaque élève : renvoie en 1 touche, utilise un relais, joue en 3 touches, attaque.'],cons:['3 touches maximum par équipe ; rotation à chaque reprise d’engagement.'],reus:'Constituer pour la suite deux groupes de niveau et des équipes de force proche entre elles.'}
 ],bilan:'Où marque-t-on le plus de points en 1c1 ? (Au fond du terrain adverse.) Pourquoi a-t-on besoin d’un partenaire ?'},
 {id:'p2',n:'S2',short:'Continuité à 2',status:'next',title:'Assurer la continuité à deux',lead:'Ne plus laisser tomber la balle : recevoir haut, devant son partenaire, et s’organiser à deux.',tl:[['Échauffement','12'],['Réception par 4','15'],['2c2 réceptionneur-passeur','15'],['2c2 à contrat','27'],['Bilan','6']],eval:[['e1','Degré 2 : réception en manchette en situation favorable, jeu en relais.'],['a2','Les élèves N1–N2 du test refont la fiche « continuité » à la place de l’exercice 1.']],warm:'Routine type, puis volleython (battre son record de S1).',ex:[
  {t:'Réception par 4',d:'15 min',k:'Thierry',sch:'fourn',disp:'Par 4 : 1 fournisseur d’un côté ; de l’autre, 2 réceptionneurs en tournante et 1 renvoyeur dans la zone cible. Rôles changés toutes les 4 min.',deroul:['Le fournisseur lance à deux mains par en dessous.','Le réceptionneur joue en manchette vers la zone cible, puis passe derrière l’autre.','Le renvoyeur rend la balle au fournisseur.','Évolution : le fournisseur renvoie directement par-dessus le filet.'],cons:['Plateau tôt, immobile, orienté vers la zone cible ; ce sont les jambes qui montent la balle.'],reus:'7 réceptions sur 10 attrapées dans la zone cible.',moins:'Lancer plus haut, plus court ; ballon plus léger.',plus:'Lancer à droite et à gauche du réceptionneur.'},
  {moins:"Engagement lancé à deux mains, droit sur un joueur ; la passe peut être bloquée.",plus:"Engagement en service ; renvoi visé en zone arrière adverse = 2 points.",t:'2c2 réceptionneur-passeur',d:'15 min',k:'Thierry',sch:'cote',disp:'2c2, côte à côte au départ, 3 touches par équipe ; séquences de 2 min, décaler d’un terrain vers la droite.',deroul:['Le réceptionneur annonce « j’ai » et joue haut devant son partenaire.','Le partenaire devient passeur : passe haute près du filet.','Le réceptionneur monte et renvoie ; on se replace côte à côte.'],cons:['Se désigner réceptionneur tôt ; balle haute en zone avant.'],reus:'6 constructions en 3 touches sur 10.'},
  {t:'2c2 à contrat',d:'27 min',k:'Jeu · Thierry',sch:'cote',disp:'2c2, matchs de 5 min, engagement en passe depuis les 3 m ; après chaque match, l’équipe se décale vers la gauche.',deroul:['Contrat : moins de 3 ballons non touchés par match.','Ballon bloqué autorisé en réception ; dans ce cas, renvoi obligatoire au partenaire à 10 doigts.','Points : victoire avec contrat 4, victoire sans contrat 3, défaite avec contrat 2, défaite sans contrat 1.'],cons:['Après chaque match, noter son résultat.'],reus:'Respecter le contrat sur 3 matchs.',plus:'Blocage interdit en zone avant ; bonus si on marque en zone arrière.'}
 ],bilan:'Côte à côte ou l’un derrière l’autre : quels avantages, quels inconvénients ?'},
 {id:'p3',n:'S3',short:'Servir',status:'next',title:'Servir : choisir son service et le rendre sûr',lead:'Chaque élève trouve le service qu’il réussit, depuis la distance qu’il maîtrise : le jour de l’évaluation, il servira 3 fois de suite.',tl:[['Échauffement','12'],['Test + ateliers service','20'],['Service et réception notée','15'],['2c2 montante-descendante','22'],['Bilan','6']],eval:[['e1','Service placé (degré 2) puis service placé efficace (degré 4). Le choix du service est prévu par le référentiel.']],warm:'Routine type, puis service-réception par 2.',ex:[
  {fixe:"Test puis ateliers : chaque élève travaille déjà à son niveau (N1 à N4). On change d'atelier à 15 sur 20.",t:'Test puis ateliers de service',d:'20 min',k:'Thomas et Carine',sch:'debservice',disp:'5 min de test : 10 services derrière la ligne (N1 0–3 · N2 4–6 · N3 7–9 · N4 10). Puis 4 ateliers le long des lignes, 1 ballon pour 2, plots tous les mètres dans son camp.',deroul:['N1 : main ferme. Ballon qui rebondit, frappé en main basse ; puis cuillère depuis les 3 m, on recule d’un mètre après chaque réussite.','N2 : cuillère derrière la ligne de fond.','N3 : service placé dans des zones cibles.','N4 : service tennis dans les cibles ; 3 services d’affilée réussis.'],cons:['Pieds décalés, pied avant opposé à la main qui frappe.','Main qui tient le ballon bras tendu devant soi.','Corps gainé qui avance au moment de la frappe ; main ferme.'],reus:'15 services sur 20 pour passer à l’atelier suivant.'},
  {moins:"Service remplacé par un lancer à deux mains depuis les 3 m.",plus:"Service ciblé sur un réceptionneur ; le passeur fait la vraie passe.",t:'Fil rouge 1 · Service et réception notée',d:'15 min',k:'Première apparition du fil rouge',sch:'recep',four:'4 au service : chacun sert 3 fois de suite, puis note la réception pendant que le suivant sert. 4 en réception : 3 réceptionneurs + 1 passeur ; rotation d’une place après chaque série de 3 services.',disp:'Par terrain : 4 au service (3 services chacun, de la distance choisie), 3 réceptionneurs + 1 passeur qui attrape dans la zone cible. 12 services puis on inverse.',deroul:['Réception notée de 0 à 3 par un élève de l’équipe au service.'],cons:['« J’ai » avant que le ballon passe le filet.'],reus:'Service : 9 sur 12 au-delà des 3 m adverses. Réception : moyenne au moins 1,5.'},
  {moins:"Service depuis la distance de son atelier, cuillère autorisée ; couloir de 2 m.",plus:"Service derrière la ligne ; renvoi en 3 touches obligatoire, sinon le point ne compte pas.",t:'2c2 montante-descendante',d:'22 min',k:'Jeu · Thomas',sch:'kob',disp:'2c2 sur couloirs, matchs de 3 min.',deroul:['Chaque joueur sert 3 fois de suite (règle de l’épreuve), de la distance de son atelier.','Service non renvoyé par l’adversaire = 3 points.'],cons:['Je sers de la distance que je réussis.'],reus:'Monter d’au moins un terrain.'}
 ],bilan:'Chaque élève écrit son service d’épreuve : cuillère ou tennis, d’où ? Il le travaillera jusqu’à S8.'},
 {id:'p4',n:'S4',short:'Vers le passeur',status:'next',title:'Recevoir vers le passeur, passer au 4c4',lead:'Construire la liaison réceptionneur → passeur → attaque, puis la transférer en 4c4.',tl:[['Échauffement d’équipe','12'],['Réception notée + vraie passe','15'],['3c3 en triangle','15'],['Premier 4c4, 3 tours','27'],['Bilan','6']],eval:[['e1','Degré 3 : passe et manchette hautes, non-porteur qui offre des relais.'],['a3','Choix des 2 rôles (arbitre et coach en priorité) et de la répartition AFL2/AFL3.']],warm:'Échauffement d’équipe, première fois : présente la fiche (2 min), puis général 3 min, spécifique 2 (passe au numéro possible), cheville-épaule et gainage 2, travail ciblé 5. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {moins:"Le passeur bloque encore la balle avant de la relancer vers le poste 4.",plus:"Service ciblé ; l'attaquant noté 3 doit attaquer en suspension.",t:'Fil rouge 1 · Réception notée + vraie passe',d:'15 min',k:'Liaison réception → passe',sch:'recep',four:'4 au service : chacun sert 3 fois de suite, puis note la réception pendant que le suivant sert. 4 en réception : 3 réceptionneurs + 1 passeur ; rotation d’une place après chaque série de 3 services.',disp:'Comme en S3, mais le passeur ne bloque plus : il fait une vraie passe haute vers le poste 4 ; le réceptionneur noté 2 ou 3 attaque. Engagement lancé à deux mains pour les débutants.',deroul:['Réception notée de 0 à 3.','Passeur dans la zone cible, épaules perpendiculaires au filet.'],cons:['Le réceptionneur monte vers le filet après sa réception.'],reus:'Moyenne de réception au moins 1,8 ; 5 attaques sur 12.'},
  {t:'3c3 en triangle',d:'15 min',k:'Thierry et Carine',sch:'tri3',four:'3 joueurs sur le terrain + 1 remplaçant-coach qui ramasse et observe le passeur ; il entre à chaque changement de passeur (tous les 5 points).',disp:'3c3, un passeur avant fixe, deux arrières 1 m derrière les 3 m. Terrain 4,5 × 7 m de chaque côté, engagement en passe.',deroul:['Réception sur le passeur, passe, renvoi par le réceptionneur.','On change de passeur tous les 5 points.'],cons:['Le passeur se tourne vers le réceptionneur et lui passe à 1 m du filet.'],reus:'Gagner le match en jouant en 3 touches.',moins:'Paliers de Carine : 1) ballon collé partout ; 2) collé dans son terrain mais renvoi en passe ; 3) seul le passeur peut coller.',plus:'Tout en passe ; renvoi interdit dans les 3 m adverses.'},
  {moins:"Engagement en passe pendant les 3 tours ; ballon bloqué autorisé à la 2e touche.",plus:"Vrai service dès le tour 2 ; point en 3 touches = 2 points.",t:'Premier 4c4, 3 tours',d:'27 min',k:'Jeu',sch:'eval4',four:'Les 6 équipes jouent sur 3 terrains. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point.',disp:'Tournoi à 3 terrains (bouton Tournoi), 3 tours de 7 min, 1 min de changement. Équipes de 4 mixtes, de force égale entre elles.',deroul:['Tours 1 et 2 : engagement en passe ; tour 3 : vrai service (3 de suite, au-delà des 3 m adverses).','Réception obligatoire vers le passeur avant tout renvoi.'],cons:['Le passeur est décalé à droite, dans la zone cible.'],reus:'La moitié des points marqués en 3 touches.'}
 ],bilan:'Où se place le passeur quand la balle est chez l’adversaire ? Quand elle arrive chez nous ?'},
 {id:'p5',n:'S5',short:'Mettre en difficulté',status:'next',title:'Mettre l’adversaire en difficulté',lead:'Passer du renvoi « cadeau » au renvoi qui gêne : au fond, sur les côtés, puis vers le bas.',tl:[['Échauffement d’équipe','12'],['Attaque à 4','15'],['1c1 à zones','15'],['4c4 barème, 3 tours','27'],['Bilan','6']],eval:[['e2','Degré 3 : ballons tendus au fond du terrain adverse.'],['e1','Le smash apparaît (degré 3).'],['a2','Premier échauffement autonome observé.']],warm:'Échauffement d’équipe en autonomie avec la fiche ; le coach remplit le carnet. <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Fil rouge 2 · Attaque à 4',d:'15 min',k:'Carine',sch:'att3',four:'Lanceur, passeur, attaquant d’un côté ; le 4e, en face, attrape la balle attaquée et la rend au lanceur. Rotation d’une place à chaque ballon.',disp:'Par équipe de 4 sur un demi-terrain dans la longueur, 2 ballons.',deroul:['Le lanceur envoie haut au passeur.','Le passeur fait une passe haute au niveau des 3 m.','Temps 1 : l’attaquant frappe à une main, pieds au sol, dans la diagonale.','Temps 2 : saut pieds joints ; puis le passeur rapproche le ballon du filet.'],cons:['Viser le ballon avec la main qui ne frappe pas.','Frapper gainé, bras tendu, main dure, devant soi.'],reus:'7 frappes sur 10 vers le bas dans le terrain.',moins:'Passe en collé.'},
  {moins:"Zone avant réduite à 2 m ; le renvoi peut se faire en 2 touches.",plus:"Zone arrière réduite à 2 m depuis la ligne de fond ; renvoi en 1 touche seulement.",t:'1c1 à zones',d:'15 min',k:'Thomas',sch:'zones1c1',four:'2 jouent en 1c1 (un de chaque côté), 2 comptent les points (un par joueur). On échange toutes les 2 min.',disp:'Par équipe de 4 sur un demi-terrain, contre un adversaire de même niveau, engagement alterné depuis les 3 m.',deroul:['Ballon au sol en zone avant = 1 point ; en zone arrière = 10 points.'],cons:['Mains en triangle, flexion puis extension des jambes et des bras pour aller loin.'],reus:'N1 < 40 · N2 40–70 · N3 70–100 · N4 > 100 sur 3 matchs.'},
  {moins:"Engagement en passe pendant les 3 tours ; ballon non touché = 3 points maintenu.",plus:"Vrai service dès le tour 2 ; feinte réussie = 2 points.",t:'4c4 au barème de l’épreuve, 3 tours',d:'27 min',k:'Jeu',sch:'eval4',four:'Les 6 équipes jouent sur 3 terrains. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point.',disp:'Tournoi à 3 terrains (bouton Tournoi), 3 tours de 7 min (ou 12 points), 1 min de changement ; 3 min de présentation.',deroul:['Tours 1 et 2 : engagement en passe ; tour 3 : vrai service.','Attaque en suspension vers le bas = 3 points ; ballon non touché = 3 points.'],cons:['Viser le fond ou les côtés plutôt que le centre.'],reus:'Au moins un point à 3 par match.'}
 ],bilan:'Qu’est-ce qui rapporte le plus de points ? Qu’est-ce qu’il faut pour pouvoir attaquer ?'},
 {id:'p6',n:'S6',short:'Construire le renvoi',status:'next',title:'Construire collectivement le renvoi',lead:'Chacun connaît son rôle selon qui reçoit, et l’équipe rejoue la balle facile.',tl:[['Échauffement d’équipe','12'],['Lanceur-receveur-passeur','15'],['4c2 zone des 3 m interdite','15'],['Grand point / petit point, 3 tours','27'],['Bilan','6']],eval:[['e2','Degré 3 : attaques régulières en 3 touches.'],['a3','Arbitrage observé pendant le 4c4.']],warm:'Échauffement d’équipe avec la fiche. Pendant le travail ciblé, le coach pose la question de Thomas : que doit faire le receveur, le passeur, l’attaquant ? <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {t:'Lanceur-receveur-passeur',d:'15 min',k:'Thomas · rôles automatiques de Carine',sch:'lrp',four:'Lanceur, receveur, passeur, et un défenseur dans le camp adverse qui tente de défendre le renvoi puis rend le ballon au lanceur. Rotation d’une place tous les 5 ballons. Variante de Carine : le lanceur + J1, J2, J3.',disp:'Par équipe, demi-terrain : lanceur sur la ligne des 3 m, receveur au milieu du terrain, passeur dans la zone cible.',deroul:['Le lanceur envoie à deux mains au receveur.','Le receveur joue sur le passeur et monte vers le filet.','Le passeur lui remet la balle près du filet ; renvoi dans le camp adverse.','Variante à 3 (Carine) : si J2 ou J3 reçoit, J1 passe ; si J1 reçoit, J3 passe.'],cons:['Passe à dix doigts, ballon pris au-dessus de la tête.','Parler le plus tôt possible.'],reus:'7 renvois réussis sur 10.',moins:'Le receveur envoie directement au passeur, qui renvoie.',plus:'Lanceur de l’autre côté du filet, 2 receveurs qui s’annoncent, un défenseur adverse.'},
  {t:'4c2, zone des 3 m interdite',d:'15 min',k:'Carine',sch:'quatre2',four:'Équipe de 4 : les 4 jouent. Autre équipe : 2 jouent, 1 arbitre, 1 ramasseur ; les paires échangent après 6 engagements.',disp:'Équipe de 4 contre équipe de 2. Auto-arbitrage : le serveur annonce le score, son équipe en premier.',deroul:['L’équipe de 4 construit en 3 touches obligatoires et ne peut pas viser la zone des 3 m adverse.','L’équipe de 2 attaque en passe haute dans les espaces libres ; retour direct autorisé.','Seule l’équipe de 2 engage.'],cons:['Équipe de 4 : regarder où sont les 2 adversaires avant de renvoyer.'],reus:'L’équipe de 4 gagne la série de 12 engagements.',moins:'Seul le passeur peut coller.'},
  {moins:"La balle facile est lancée depuis les 3 m, en cloche, au centre du terrain.",plus:"La balle facile est lancée vers un joueur ciblé ; l'équipe doit attaquer en 3e touche.",t:'Grand point / petit point, 3 tours',d:'27 min',k:'Jeu · transition',sch:'grandpoint',four:'Les 6 équipes jouent sur 3 terrains. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point. La balle facile est lancée par un joueur de l’équipe qui a gagné le premier échange.',disp:'Tournoi à 3 terrains (bouton Tournoi), 3 tours de 7 min, 1 min de changement.',deroul:['Chaque échange commence par un engagement en passe.','Dès qu’il se termine, l’équipe qui l’a gagné lance une balle facile (à deux mains, par-dessus le filet) à l’autre équipe.','L’équipe qui gagne les deux échanges marque le grand point ; sinon personne ne marque.','Sur la balle facile, toute l’équipe crie « facile ! » et se replace en réception avant de construire en 3 touches.'],cons:['Se replacer pendant que la balle est en l’air.'],reus:'Gagner au moins la moitié des balles faciles reçues.'}
 ],bilan:'Je reçois : que fais-je ensuite ? Je ne reçois pas : où vais-je ?'},
 {id:'p7',n:'S7',short:'Organisation 4c4',status:'next',title:'S’organiser à 4 avec un passeur décalé',lead:'Choisir une organisation d’équipe, la tenir en match, l’ajuster au temps mort.',tl:[['Échauffement d’équipe','12'],['Losange ou carré, 2 matchs','20'],['Tournoi à thèmes, 4 tours','37'],['Bilan','6']],eval:[['e2','Projet d’équipe : choisir l’organisation la plus efficace selon ses joueurs.'],['a3','Coach et arbitre observés pendant le tournoi.']],warm:'Échauffement d’équipe avec la fiche. Une équipe qui n’a jamais choisi l’axe Service le prend aujourd’hui (série de 3, comme le jour J). <a href="#" data-go="equipe">Fiche Échauffement d’équipe</a>',ex:[
  {moins:"Garder l'organisation la plus simple (losange) ; retour direct autorisé dès la 2e touche.",plus:"Changer d'organisation à chaque rotation ; construction en 3 touches obligatoire sur toutes les balles.",t:'Losange ou carré, 2 matchs',d:'20 min',k:'Carine · FFVB',sch:'losange',four:'Les 6 équipes jouent sur 3 terrains. Auto-arbitrage : l’équipe au service annonce le score, le sien en premier ; en cas de désaccord, on rejoue le point.',disp:'3 min d’explication sur un terrain, puis tours 1 et 2 de la rotation à 3 terrains (7 min par match, 1 min de changement). Une équipe change d’organisation entre les deux matchs. 1 min de bilan à la fin.',deroul:['Losange : le joueur avant est le passeur ; quand la balle arrive, il se décale dans la zone cible (entre les postes 2 et 3).','Carré : le passeur est l’avant droit ; il passe à l’avant gauche.','Construction en 3 touches obligatoire ; retour direct autorisé si l’adversaire envoie dans les 3 m.'],cons:['À la fin, chaque équipe choisit son organisation et dit pourquoi.'],reus:'L’équipe sait expliquer son choix.'},
  {moins:"Tour 1 rallongé ; le ballon bloqué reste autorisé à la 2e touche.",plus:"Dès le tour 2, point en 3 touches = 2 points et vrai service.",t:'Tournoi à thèmes, 4 tours',d:'37 min',k:'Jeu · Thierry',sch:'eval4',four:'4 équipes jouent sur 2 terrains ; les 2 autres arbitrent, une par terrain (1 arbitre, 2 juges de ligne, 1 coach). Arbitre et coach observés.',disp:'Tournoi à 2 terrains, arbitres cochés (bouton Tournoi), tours 1 à 4 : matchs de 7 min, 1 min de changement. Équipes mixtes (2 filles, 2 garçons).',deroul:['Tour 1 : réception obligatoire dans son camp.','Tours 2 et 3 : en plus, ballon au sol sans être touché = 3 points.','Tour 4 : vrai service, barème de l’épreuve, l’équipe joue l’organisation qu’elle a choisie.'],cons:['Temps mort d’1 min par match : le coach donne un seul conseil.'],reus:'Les points en 3 touches deviennent majoritaires au tour 4.'}
 ],bilan:'Losange ou carré : lequel nous fait marquer le plus ? Pourquoi ? À la fin : distribue la fiche « Mes choix pour l’épreuve » (onglet Fiche d’évaluation), à rendre signée en S8.'},
 {id:'p8',n:'S8',short:'Rôles · tournoi blanc',status:'next',title:'Rôles et tournoi blanc',lead:'Préparer l’évaluation : partenaire d’entraînement, règles d’arbitrage, puis un tournoi aux conditions du jour J.',tl:[['Échauffement d’avant-match','12'],['Duo en or + quiz d’arbitrage','20'],['Tournoi blanc','37'],['Bilan','6']],eval:[['a2','Échauffement d’avant-match mené seul ; records de S1 refaits pour mesurer les progrès.'],['a3','Partenaire d’entraînement (duo en or) ; arbitre (quiz + match).']],warm:'Échauffement d’avant-match mené par l’équipe seule.',ex:[
  {moins:"Matchs de 4 min avec engagement lancé ; quiz en binôme.",plus:"Duo : renvoi en 3 touches obligatoire ; quiz chronométré, réponses à justifier.",t:'Duo en or puis quiz d’arbitrage',d:'20 min',k:'Thierry · Carine',sch:'kob',four:'2 duos par équipe ; on change de partenaire à chaque match pour jouer avec chacun de ses 3 coéquipiers.',disp:'Chaque équipe forme 2 duos qui jouent en 2c2 contre les duos d’une autre équipe, matchs de 4 min (15 min). Puis quiz de 5 min au bord du terrain.',deroul:['Chaque élève joue avec chacun de ses 3 coéquipiers et note ses victoires.','Quiz : ordre des gestes de l’arbitre à la fin d’un échange, règles du service, numéros des postes et rotation, deux particularités du poste 1.'],cons:['Le joueur le plus à l’aise adapte son jeu à son partenaire : c’est le rôle de partenaire d’entraînement.'],reus:'Gagner la moitié de ses matchs ; 4 réponses justes sur 4 pour les arbitres.'},
  {fixe:"Tournoi blanc : conditions de l'évaluation. Seuls les aménagements fixés s'appliquent (service choisi en S3, ballon collé selon le niveau).",t:'Tournoi blanc',d:'37 min',k:'Conditions de l’évaluation',sch:'eval4',four:'La 3e équipe : 1 arbitre, 2 juges de ligne, 1 gestionnaire (score, feuille de match).',disp:'Exactement l’organisation de S9 (bouton S9).',deroul:['Rencontres de 12 points au tie-break, 3 services par joueur, temps mort d’1 min.','Aménagements fixés : service choisi en S3, ballon collé selon le niveau.'],cons:['Le prof annonce à chaque élève son degré provisoire.'],reus:'Tout le monde connaît l’organisation du jour J.'}
 ],bilan:'Comparer ses records de S1 et de S8 : sur quoi ai-je progressé ?'},
 {id:'p9',n:'S9',short:'Évaluation',status:'eval',title:'Évaluation de Première',lead:'Tournoi en 4c4 avec les règles du référentiel du lycée. En Première, l’évaluation sert à préparer la Terminale.',evalPage:true,evalRender:()=>renderEvalP()}
];
